import { Observable } from 'rxjs';

export const DECENTR_LINK = 'https://decentr.net/';
export const DECENTR_EXPLORER = 'https://explorer.decentr.net/transactions/';
export const METAMASK_LINK = 'https://metamask.io/';
export const METAMASK_EXPLORER = 'https://etherscan.io/tx/';

export const MICRO_DIVISOR = 1000000;

export interface NetworkDescription {
  name: string;
  chainId: string | number;
}

export enum SwapDestinationNetwork {
  DEC = 'decentr',
  ETH = 'ethereum',
}

export interface NetworkService {
  connect(): Promise<boolean>;
  getBalance(): Observable<string>;
  getNetwork(): Observable<NetworkDescription>;
  getWalletAddress(): Observable<string>;
  isAPIAvailable(): boolean;
  isConnected(): Observable<boolean>;
  isConnecting(): Observable<boolean>;
  transferCoin(amountFrom: string, receiverAddress?: string): Promise<string>;
}
